$ErrorActionPreference = "Stop"
$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$python = Join-Path $root ".venv\Scripts\python.exe"
$approvalPath = Join-Path $pkg "ahos\owner_approval.py"
$testPath = Join-Path $pkg "tests\test_owner_approval.py"
$patcher = Join-Path $env:TEMP "ahos-038-patch.py"

Write-Host "=== AHOS-038 OWNER APPROVAL INBOX ==="
Write-Host "LOCAL ONLY - OpenAI API calls: 0 - Paid API spend: USD 0"

if (-not (Test-Path $python)) { throw "Python venv not found." }
if (-not (Test-Path $pkg)) { throw "AHOS package not found." }

[IO.File]::WriteAllBytes($approvalPath,[Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($testPath,[Convert]::FromBase64String(""))
$patchText=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
$patchText=$patchText.Replace("__PKG__",$pkg.Replace("\","\\"))
[IO.File]::WriteAllText($patcher,$patchText,(New-Object System.Text.UTF8Encoding($false)))

& $python $patcher
if($LASTEXITCODE -ne 0){ throw "AHOS-038 patch failed." }

$old=$env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH=$pkg
    & $python -m pytest tests\test_owner_approval.py -q
    if($LASTEXITCODE -ne 0){ throw "Approval tests failed." }
    & $python -m pytest -q
    if($LASTEXITCODE -ne 0){ throw "Full AHOS tests failed." }
}
finally {
    Pop-Location
    $env:PYTHONPATH=$old
    Remove-Item $patcher -Force -ErrorAction SilentlyContinue
}

git -C $ws add ahos_core/ahos/owner_approval.py ahos_core/ahos/mission_orchestrator.py ahos_core/ahos/autonomous_company.py ahos_core/tests/test_owner_approval.py ahos_core/AHOS_BACKLOG.json
$staged=git -C $ws diff --cached --name-only
if($staged){
    git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "feat(ahos): add persistent owner approval inbox"
    if($LASTEXITCODE -ne 0){ throw "git commit failed." }
    git -C $ws push origin HEAD
    if($LASTEXITCODE -ne 0){ throw "git push failed." }
}

Write-Host ""
Write-Host "=== AHOS-038 COMPLETE ==="
Write-Host "Persistent owner approval inbox: PASS"
Write-Host "WAITING_OWNER_APPROVAL state: PASS"
Write-Host "Protected-work execution gate: PASS"
Write-Host "Explicit owner approve/reject: PASS"
Write-Host "Approved mission safe resume: PASS"
Write-Host "AI self-approval: BLOCKED"
Write-Host "Full AHOS tests: PASS"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host "CORE ROADMAP REMAINING: AHOS-039 through AHOS-042."
